    correction: [{"quoi":"القاعدة","math":"عدد يقبل القسمة على 15 إذا و فقط إذا قبلها على 3 و على 5 ; و القسمة على 5 تفرض رقم آحاد يساوي 0 أو 5"},{"quoi":"رقم الآحاد إذن","math":"الرقم الأخير هو 0 أو 5"},{"quoi":"و مجموع الأرقام مضاعف للثلاثة","math":"مثلا <span dir=\"ltr\" class=\"expr\">4 + 0 + 5 = 9</span>"},{"quoi":"نتحقّق من أوّل الحلول","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">405</span><span class=\"den\">15</span></span> = 27</span>"},{"quoi":"و من آخرها","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">765</span><span class=\"den\">15</span></span> = 51</span>"},{"quoi":"نعدّ الحلول بالمسح الكامل","math":"<span dir=\"ltr\" class=\"expr\">10 = 10</span>"},{"quoi":"النتيجة","math":"يوجد 10 أعداد: 405 و 450 و 465 و 540 و 570 و 645 و 675 و 705 و 750 و 765"}],
