    correction: [{"quoi":"القاعدة","math":"مركز الثقل يقع على كلّ متوسّط على بعد ثلثيه من الرأس"},{"quoi":"المثلّث BSJ قائم في S","math":"لأنّ J من [AS] و المثلّث ASB قائم في S"},{"quoi":"نحسب SJ","math":"<span dir=\"ltr\" class=\"expr\">SJ = 4</span>"},{"quoi":"نطبّق نظرية فيتاغور","math":"<span dir=\"ltr\" class=\"expr\">BJ<sup>2</sup> = 16 + 36</span>"},{"quoi":"نبسّط الجذر","math":"<span dir=\"ltr\" class=\"expr\">BJ = 2<span class=\"rad\"><span class=\"rcd\">13</span></span></span>"},{"quoi":"نأخذ الثلثين","math":"<span dir=\"ltr\" class=\"expr\">BG = 2 × <span class=\"frac\"><span class=\"num\">BJ</span><span class=\"den\">3</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">BG = <span class=\"frac\"><span class=\"num\">4<span class=\"rad\"><span class=\"rcd\">13</span></span></span><span class=\"den\">3</span></span></span>"}],
