    correction: [{"quoi":"القاعدة","math":"<span dir=\"ltr\" class=\"expr\">(u - v)<sup>2</sup> = u<sup>2</sup> - 2uv + v<sup>2</sup></span> ; و ضلع مربّع مساحته S هو <span dir=\"ltr\" class=\"expr\"><span class=\"rad\"><span class=\"rcd\">S</span></span></span>"},{"quoi":"ننشر","math":"<span dir=\"ltr\" class=\"expr\">(2 - <span class=\"rad\"><span class=\"rcd\">3</span></span>)<sup>2</sup> = 4 - 4<span class=\"rad\"><span class=\"rcd\">3</span></span> + 3</span>"},{"quoi":"نختصر","math":"<span dir=\"ltr\" class=\"expr\">4 - 4<span class=\"rad\"><span class=\"rcd\">3</span></span> + 3 = 7 - 4<span class=\"rad\"><span class=\"rcd\">3</span></span></span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr\">a = (2 - <span class=\"rad\"><span class=\"rcd\">3</span></span>)<sup>2</sup></span>"},{"quoi":"نجمع العددين","math":"<span dir=\"ltr\" class=\"expr\">a + b = 4 - 2<span class=\"rad\"><span class=\"rcd\">3</span></span></span>"},{"quoi":"و هذا المجموع مربّع","math":"<span dir=\"ltr\" class=\"expr\">(<span class=\"rad\"><span class=\"rcd\">3</span></span> - 1)<sup>2</sup> = 4 - 2<span class=\"rad\"><span class=\"rcd\">3</span></span></span>"},{"quoi":"و العدد <span dir=\"ltr\" class=\"expr\"><span class=\"rad\"><span class=\"rcd\">3</span></span> - 1</span> موجب","math":"<span dir=\"ltr\" class=\"expr\">1 &lt; <span class=\"rad\"><span class=\"rcd\">3</span></span></span>"},{"quoi":"النتيجة","math":"ضلع المربّع يساوي <span dir=\"ltr\" class=\"expr\"><span class=\"rad\"><span class=\"rcd\">3</span></span> - 1</span>"}],
